<?php require 'includes/functions.php';$pageTitle='Our Brands';require 'includes/header.php';?><div class="page-head"><div class="container"><span class="eyebrow">THE HOUSES WE CARRY</span><h1>Our Brands</h1></div></div><section class="container section category-grid"><?php foreach(query('SELECT b.*,COUNT(p.id) product_count FROM brands b LEFT JOIN products p ON p.brand_id=b.id AND p.is_active=1 GROUP BY b.id ORDER BY b.name')->fetchAll() as $b):?><a class="category-card brand-card" href="<?=e(url('new-arrivals.php?brand='.$b['id']))?>"><h2><?=e($b['name'])?></h2><p class="muted"><?=$b['product_count']?> fragrances</p><span>Explore the house ↗</span></a><?php endforeach;?></section><?php require 'includes/footer.php';?>
